package auth

import("context";"crypto/rand";"crypto/sha256";"encoding/hex";"errors";"net";"net/mail";"strings";"github.com/jackc/pgx/v5/pgxpool";"github.com/REinstall-SyS/WaitlistFair/internal/appointments")
type Service struct{DB *pgxpool.Pool;AppURL string}
type Identity struct{ID string `json:"id"`;Email string `json:"email"`;Name string `json:"display_name"`;Timezone string `json:"timezone"`;Notifications bool `json:"notifications"`;CSRF string `json:"csrf"`}
func Random()string{b:=make([]byte,32);if _,e:=rand.Read(b);e!=nil{panic(e)};return hex.EncodeToString(b)}
func Hash(token string)string{h:=sha256.Sum256([]byte(token));return hex.EncodeToString(h[:])}
func(s *Service)Request(ctx context.Context,email,remote string)error{email=strings.ToLower(strings.TrimSpace(email));a,e:=mail.ParseAddress(email);if e!=nil||a.Address!=email||len(email)>254{return errors.New("enter a valid email address")};host,_,_:=net.SplitHostPort(remote);tx,e:=s.DB.Begin(ctx);if e!=nil{return e};defer tx.Rollback(ctx);for _,limit:=range []struct{key string;n int}{{"email:"+email,5},{"ip:"+host,100}}{var count int;e=tx.QueryRow(ctx,`INSERT INTO rate_limits(key,expires_at) VALUES($1,clock_timestamp()+interval '15 minutes') ON CONFLICT(key) DO UPDATE SET count=CASE WHEN rate_limits.expires_at<clock_timestamp() THEN 1 ELSE rate_limits.count+1 END,expires_at=CASE WHEN rate_limits.expires_at<clock_timestamp() THEN clock_timestamp()+interval '15 minutes' ELSE rate_limits.expires_at END RETURNING count`,Hash(limit.key)).Scan(&count);if e!=nil{return e};if count>limit.n{return tx.Commit(ctx)}}
 var id string;e=tx.QueryRow(ctx,`INSERT INTO users(email,display_name) VALUES($1,$2) ON CONFLICT(email) DO UPDATE SET email=EXCLUDED.email RETURNING id`,email,strings.Split(email,"@")[0]).Scan(&id);if e!=nil{return e};token:=Random();if _,e=tx.Exec(ctx,`INSERT INTO magic_tokens(token_hash,user_id,expires_at) SELECT $1,$2,clock_timestamp()+interval '15 minutes' WHERE EXISTS(SELECT 1 FROM users WHERE id=$2 AND deleted_at IS NULL)`,Hash(token),id);e!=nil{return e};if e=appointments.Event(ctx,tx,"MagicLink",map[string]string{"to":email,"subject":"Your WaitlistFair sign-in link","body":"Sign in to WaitlistFair. This single-use link expires in 15 minutes.\n\n"+s.AppURL+"/auth/verify#token="+token+"\n\nIf you did not request this email, you can ignore it."});e!=nil{return e};return tx.Commit(ctx)}
func(s *Service)Verify(ctx context.Context,token string)(string,error){if len(token)!=64{return "",errors.New("this sign-in link is invalid or expired")};tx,e:=s.DB.Begin(ctx);if e!=nil{return "",e};defer tx.Rollback(ctx);var user string;e=tx.QueryRow(ctx,`DELETE FROM magic_tokens WHERE token_hash=$1 AND expires_at>clock_timestamp() RETURNING user_id`,Hash(token)).Scan(&user);if e!=nil{return "",errors.New("this sign-in link is invalid or expired")};session:=Random();_,e=tx.Exec(ctx,`INSERT INTO sessions(token_hash,user_id,csrf_token,expires_at) SELECT $1,$2,$3,clock_timestamp()+interval '7 days' WHERE EXISTS(SELECT 1 FROM users WHERE id=$2 AND deleted_at IS NULL)`,Hash(session),user,Random());if e!=nil{return "",e};return session,tx.Commit(ctx)}
func(s *Service)Session(ctx context.Context,token string)(Identity,error){var u Identity;e:=s.DB.QueryRow(ctx,`SELECT u.id,u.email,u.display_name,u.timezone,u.notifications,s.csrf_token FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=$1 AND s.expires_at>clock_timestamp() AND u.deleted_at IS NULL`,Hash(token)).Scan(&u.ID,&u.Email,&u.Name,&u.Timezone,&u.Notifications,&u.CSRF);return u,e}
func(s *Service)Logout(ctx context.Context,token string)error{_,e:=s.DB.Exec(ctx,`DELETE FROM sessions WHERE token_hash=$1`,Hash(token));return e}
func(s *Service)Delete(ctx context.Context,user string)error{tx,e:=s.DB.Begin(ctx);if e!=nil{return e};defer tx.Rollback(ctx);if _,e=tx.Exec(ctx,`SELECT id FROM users WHERE id=$1 FOR UPDATE`,user);e!=nil{return e};var active bool;if e=tx.QueryRow(ctx,`SELECT EXISTS(SELECT 1 FROM claims WHERE student_id=$1 AND state IN ('pending','confirmed') AND ends_at>clock_timestamp()) OR EXISTS(SELECT 1 FROM memberships WHERE user_id=$1 AND role IN ('admin','tutor') AND enabled)`,user).Scan(&active);e!=nil{return e};if active{return errors.New("cancel upcoming appointments, decline active offers, and transfer staff responsibilities before deleting your account")};if _,e=tx.Exec(ctx,`UPDATE waitlist_entries SET status='withdrawn' WHERE student_id=$1 AND status IN ('active','paused');`,user);e!=nil{return e};for _,q:=range []string{`DELETE FROM sessions WHERE user_id=$1`,`DELETE FROM magic_tokens WHERE user_id=$1`,`UPDATE memberships SET enabled=false WHERE user_id=$1`,`UPDATE users SET email=id::text||'@deleted.invalid',display_name='Deleted account',deleted_at=clock_timestamp(),notifications=false WHERE id=$1`}{if _,e=tx.Exec(ctx,q,user);e!=nil{return e}};return tx.Commit(ctx)}
